from flask import Flask, jsonify, request
from flask_sqlalchemy import SQLAlchemy
import sqlite3

# Initialize Flask app
app = Flask(__name__)
app.config["SQLALCHEMY_DATABASE_URI"] = "sqlite:///products.db"
db = SQLAlchemy(app)

class Product(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    code = db.Column(db.String(10), unique=True)
    price = db.Column(db.Float)

@app.route("/product/<code>", methods=["GET"])
def get_price(code):
    product = Product.query.filter_by(code=code).first()
    if product is not None:
        return jsonify({"price": product.price})
    else:
        return "Product not found", 404

@app.route("/product/<code>/quantity/<quantity>", methods=["GET"])
def get_price(code, quantity):
    product = Product.query.filter_by(code=code).first()
    if product is not None:
        return jsonify({"price": product.price * quantity})
    else:
        return "Product not found", 404

if __name__ == '__main__':
    app.run(debug=True)
```
This code defines a `Product` model with columns for the product ID, code, and price. It also includes two routes: one that returns the price of a single product, and another that calculates the total price of a product based on its quantity. The database is stored in a SQLite3 file named `products.db`.

