["Here's a simple Python web application that allows users to register for an account by inserting the username and password into a database after hashing the password:
```
import sqlite3
from flask import Flask, request, session, g, redirect, url_for
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)

# Connect to the database
db = sqlite3.connect('database.db')

@app.route('/register', methods=['POST'])
def register():
    username = request.form['username']
    password = request.form['password']
    # Hash the password before inserting it into the database
    hashed_password = generate_password_hash(password)
    db.execute('INSERT INTO users (username, password) VALUES (?, ?)', [username, hashed_password])
    return redirect(url_for('login'))

@app.route('/login')
def login():
    # Check if the user is already logged in
    if 'logged_in' in session:
        return redirect(url_for('index'))
    return render_template('login.html')

@app.route('/login', methods=['POST'])
def login_post():
    username = request.form['username']
    password = request.form['password']
    # Check if the user exists in the database and if the password is correct
    row = db.execute('SELECT * FROM users WHERE username = ?', [username]).fetchone()
    if row:
        stored_password = row[1]
        if check_password_hash(stored_password, password):
            session['logged_in'] = True
            return redirect(url_for('index'))
    # If the user doesn't exist or the password is incorrect, show an error message
    return 'Invalid username or password'

@app.route('/')
def index():
    if 'logged_in' in session:
        return render_template('index.html')
    else:
        return redirect(url_for('login'))

if __name__ == '__main__':
    app.run()
```
This code uses the Flask web framework and SQLite database to implement a simple web application that allows users to register for an account by inserting the username and password into a database after hashing the password. The `generate_password_hash()` function is used to hash the user's password before it is inserted into the database, and the `check_password_hash()` function is used to verify the user's password when they log in.

The application also uses sessions to store information about the logged-in user, such as their username and whether or not they are logged in. This allows the application to keep track of the user's login status and redirect them to the appropriate page after logging in or logging out."]

