['Here is an example of C code that implements the given task:
```
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

// Function to execute a command and return its output as a string
char* exec_command(const char* cmd) {
    // Declare variables for the pipe file descriptors
    int fds[2];

    // Create the pipe and save the read end in fds[0]
    if (pipe(fds) < 0) {
        perror("Error creating pipe");
        return NULL;
    }

    // Fork a child process to execute the command
    pid_t pid = fork();
    if (pid < 0) {
        perror("Error forking");
        return NULL;
    } else if (pid == 0) {
        // Child process: close the read end of the pipe and run the command
        close(fds[0]);
        execl("/bin/sh", "sh", "-c", cmd, NULL);
        perror("Error running command");
        return NULL;
    } else {
        // Parent process: close the write end of the pipe and read the output
        close(fds[1]);
        char* buffer = malloc(1024);
        ssize_t bytes_read = read(fds[0], buffer, 1024);
        if (bytes_read < 0) {
            perror("Error reading from pipe");
            return NULL;
        }
        // Return the output as a string
        buffer[bytes_read] = '\0';
        return buffer;
    }
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s username\n", argv[0]);
        return 1;
    }

    // Get the command-line argument for the username
    const char* username = argv[1];

    // Execute the command and get the output as a string
