    printf("%s\n", input);

    return 0;
}

const char* trim_trailing_whitespace(const char* str) {
    const size_t len = strlen(str);
    while (len > 0 && isspace(str[len - 1])) {
        --len;
    }
    return substr(str, 0, len);
}
